using DroidLab.Devices;
using System.Windows;
using System.Windows.Controls;
namespace DroidLab.Desktop;
public partial class MainWindow : Window {
 private static readonly string[] Modules = ["Command Center","Device Intelligence","Diagnostics Lab","Troubleshooting Lab","ADB Workbench","Fastboot Lab","Firmware & Flashing","Recovery Center","Backup & Restoration","Technician Center","SIM & Network Lab","Security & CVE Lab","Application Manager","File & Storage Lab","Connectivity Lab","Reporting Center"];
 public MainWindow(){InitializeComponent(); Navigation.ItemsSource=Modules; DiagnosticPicker.ItemsSource=Enum.GetValues<DiagnosticKind>();DiagnosticPicker.SelectedIndex=0;BackupPicker.ItemsSource=Enum.GetValues<BackupFolder>();BackupPicker.SelectedIndex=0;RebootPicker.ItemsSource=Enum.GetValues<RebootTarget>();RebootPicker.SelectedIndex=0;Navigation.SelectedIndex=0;}
 private void Navigate(object sender, SelectionChangedEventArgs e){if(Navigation.SelectedItem is not string name)return; Heading.Text=name;bool workbench=name=="ADB Workbench"||name=="Fastboot Lab";WorkbenchPanel.Visibility=workbench?Visibility.Visible:Visibility.Collapsed;if(workbench)RefreshWorkbench();bool network=name=="SIM & Network Lab"||name=="Connectivity Lab";NetworkPanel.Visibility=network?Visibility.Visible:Visibility.Collapsed;AppsPanel.Visibility=name=="Application Manager"?Visibility.Visible:Visibility.Collapsed;StoragePanel.Visibility=name=="File & Storage Lab"?Visibility.Visible:Visibility.Collapsed;bool troubleshooting=name=="Troubleshooting Lab";TroubleshootPanel.Visibility=troubleshooting?Visibility.Visible:Visibility.Collapsed;bool technician=name=="Technician Center";TechnicianPanel.Visibility=technician?Visibility.Visible:Visibility.Collapsed;CvePanel.Visibility=name=="Security & CVE Lab"?Visibility.Visible:Visibility.Collapsed; bool ready=network||troubleshooting||name=="Security & CVE Lab"||name=="Command Center"||name=="ADB Workbench"||name=="Fastboot Lab"||name=="Device Intelligence"||name=="Diagnostics Lab"||name=="Application Manager"||name=="File & Storage Lab"; bool backup=name=="Backup & Restoration";bool recovery=name=="Recovery Center";VerifyPanel.Visibility=backup?Visibility.Visible:Visibility.Collapsed;RebootPanel.Visibility=recovery?Visibility.Visible:Visibility.Collapsed;BackupPanel.Visibility=backup?Visibility.Visible:Visibility.Collapsed;bool firmware=name=="Firmware & Flashing"; FirmwarePanel.Visibility=firmware?Visibility.Visible:Visibility.Collapsed; Description.Text=network?"Read reported SIM, radio and connectivity settings; no network changes.":troubleshooting?"Read-only battery, storage and memory assessment.":technician?"Record and search local technician service history.":name=="Security & CVE Lab"?"Read device identity to assess reported patch age and verified boot. Public CVE search is available; Import curated Android bulletin JSON for device patch correlation.":backup?"Copy accessible shared storage to a new local folder. Protected app data is not included.":recovery?"Detect recovery modes and request an explicitly confirmed reboot.":firmware?"Inspect local firmware without modifying any device. A checksum match does not establish compatibility or authenticity.":ready?"Read-only ADB and Fastboot discovery. Connect an authorized device with USB debugging enabled.":"Planned module — not implemented in this foundation build."; Scan.Visibility=ready||backup||recovery||firmware?Visibility.Visible:Visibility.Collapsed;DiagnosticPanel.Visibility=ready||backup||recovery||firmware?Visibility.Visible:Visibility.Collapsed;Output.Visibility=technician||ready||firmware||backup||recovery?Visibility.Visible:Visibility.Collapsed;Output.Clear();}
 private RecoverySession? recoverySession;
 private async void RunGuidedRecovery(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||RebootPicker.SelectedItem is not RebootTarget target){Output.Text="Select an authorized device and target.";return;}if(RecoveryBackupAck.IsChecked!=true){Output.Text="Acknowledge backup risks first.";return;}if(MessageBox.Show($"Request guided reboot of {device.Serial} to {target}?","Confirm recovery",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;recoverySession=null;GuidedRecoveryButton.IsEnabled=false;RebootButton.IsEnabled=false;try{Output.Text="Checking readiness and observing transition...";recoverySession=await GuidedRecovery.ExecuteAsync(device,target,true);Output.Text=$"{recoverySession.Status}\n{recoverySession.Detail}";}catch(Exception ex){Output.Text="Transition unverified: "+ex.Message;recoverySession=new(device.Serial,target,DateTimeOffset.UtcNow,"Unverified",ex.Message);}finally{GuidedRecoveryButton.IsEnabled=true;RebootButton.IsEnabled=true;RecoveryBackupAck.IsChecked=false;}}
 private async void ExportRecoverySession(object sender,RoutedEventArgs e){var session=recoverySession;if(session==null){Output.Text="No recovery session available.";return;}var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-Recovery.json"};if(dialog.ShowDialog()!=true)return;try{await System.IO.File.WriteAllTextAsync(dialog.FileName,System.Text.Json.JsonSerializer.Serialize(session));Output.Text="Recovery session exported.";}catch(Exception ex){Output.Text=ex.Message;}}
 private List<Device> workbenchDevices=new();
 private readonly List<string> commandHistory=new();
 private string WorkbenchTransport=>Navigation.SelectedItem as string=="Fastboot Lab"?"Fastboot":"ADB";
 private void RefreshWorkbench(){var transport=WorkbenchTransport;WorkbenchDevice.ItemsSource=workbenchDevices.Where(d=>d.Transport==transport&&d.State==(transport=="ADB"?"device":"fastboot")).ToList();WorkbenchDevice.SelectedIndex=0;CommandPicker.ItemsSource=CommandWorkbench.Catalog(transport,CommandQuery.Text);CommandPicker.SelectedIndex=0;}
 private void FilterCommands(object sender,RoutedEventArgs e){CommandPicker.ItemsSource=CommandWorkbench.Catalog(WorkbenchTransport,CommandQuery.Text);CommandPicker.SelectedIndex=0;}
 private async void ExecuteWorkbench(object sender,RoutedEventArgs e){if(WorkbenchDevice.SelectedItem is not Device device||CommandPicker.SelectedItem is not WorkbenchCommand command){Output.Text="Scan and select a device and command.";return;}if(MessageBox.Show($"Run {command.Description} on authorized device {device.Serial}? Output may contain private data.","Confirm command",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;ExecuteCommandButton.IsEnabled=false;var status="Failed";try{Output.Text=await CommandWorkbench.RunAsync(device,command.Id);status="Succeeded";}catch(Exception ex){Output.Text=ex.Message;}finally{commandHistory.Add($"{DateTimeOffset.UtcNow:O} | {device.Serial} | {command.Id} | {status}");if(commandHistory.Count>200)commandHistory.RemoveAt(0);ExecuteCommandButton.IsEnabled=true;}}
 private void ShowCommandHistory(object sender,RoutedEventArgs e){Output.Text=string.Join("\n",commandHistory);}
 private string? networkReport;
 private async void ReadNetwork(object sender,RoutedEventArgs e){networkReport=null;if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}NetworkButton.IsEnabled=false;try{Output.Text="Reading network settings...";var observations=await NetworkDiagnostics.ReadAsync(device);networkReport=System.Text.Json.JsonSerializer.Serialize(new{CollectedAt=DateTimeOffset.UtcNow,Observations=observations},new System.Text.Json.JsonSerializerOptions{WriteIndented=true});Output.Text=string.Join("\n\n",observations.Select(x=>$"{x.Name}: {x.Value}\n{x.Note}"));}catch(Exception ex){Output.Text=ex.Message;}finally{NetworkButton.IsEnabled=true;}}
 private async void ExportNetwork(object sender,RoutedEventArgs e){var report=networkReport;if(report==null){Output.Text="Read a network snapshot first.";return;}var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-Network.json"};if(dialog.ShowDialog()!=true)return;try{await System.IO.File.WriteAllTextAsync(dialog.FileName,report);Output.Text="Network report exported.";}catch(Exception ex){Output.Text=ex.Message;}}
 private bool appStorageBusy;
 private async Task AppStorageOperation(Func<Device,Task<string>> operation){if(appStorageBusy)return;if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}appStorageBusy=true;try{Output.Text=await operation(device);}catch(Exception ex){Output.Text=ex.Message;}finally{appStorageBusy=false;}}
 private async void ListApps(object sender,RoutedEventArgs e){var filter=PackageQuery.Text;await AppStorageOperation(async d=>string.Join("\n",ApplicationStorage.Packages(await Diagnostics.ReadAsync(d,DiagnosticKind.Applications),filter)));}
 private async void AppMetadata(object sender,RoutedEventArgs e){await AppStorageOperation(d=>ApplicationStorage.RunAsync(d,ApplicationStorage.PackageArguments(PackageQuery.Text.Trim())));}
 private async void InstallApp(object sender,RoutedEventArgs e){await AppStorageOperation(async d=>{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Android APK|*.apk",CheckFileExists=true};if(dialog.ShowDialog()!=true)return "Cancelled.";if(MessageBox.Show($"Install trusted APK {dialog.FileName} on {d.Serial}?","Confirm installation",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return "Cancelled.";return await ApplicationStorage.RunAsync(d,ApplicationStorage.InstallArguments(dialog.FileName));});}
 private async void UninstallApp(object sender,RoutedEventArgs e){await AppStorageOperation(async d=>{var package=PackageQuery.Text.Trim();var args=ApplicationStorage.PackageArguments(package,true);if(MessageBox.Show($"Uninstall {package} from {d.Serial}? App data may be erased.","Confirm uninstall",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return "Cancelled.";return await ApplicationStorage.RunAsync(d,args);});}
 private async void ListShared(object sender,RoutedEventArgs e){await AppStorageOperation(d=>ApplicationStorage.RunAsync(d,new[]{"shell","ls","-la",ApplicationStorage.SharedPath(SharedQuery.Text.Trim())}));}
 private async void PullShared(object sender,RoutedEventArgs e){await AppStorageOperation(async d=>{var relative=SharedQuery.Text.Trim();if(relative.Length==0)throw new ArgumentException("Select a specific shared path.");var remote=ApplicationStorage.SharedPath(relative);var dialog=new Microsoft.Win32.OpenFolderDialog();if(dialog.ShowDialog()!=true)return "Cancelled.";if(MessageBox.Show($"Copy {remote} from {d.Serial} to a new local staging folder?","Confirm copy",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return "Cancelled.";var folder=System.IO.Path.Combine(dialog.FolderName,"DroidLab-Copy-"+Guid.NewGuid().ToString("N"));System.IO.Directory.CreateDirectory(folder);return folder+"\n"+await ApplicationStorage.RunAsync(d,new[]{"pull",remote,folder});});}
 private string? troubleshootingReport;
 private async void RunTroubleshooting(object sender,RoutedEventArgs e){troubleshootingReport=null;if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}TroubleshootButton.IsEnabled=false;try{Output.Text="Collecting diagnostic snapshots...";var errors=new List<string>();async Task<string> Read(DiagnosticKind kind){try{return await Diagnostics.ReadAsync(device,kind);}catch(Exception ex){errors.Add(kind+": "+ex.Message);return "";}}var battery=await Read(DiagnosticKind.Battery);var storage=await Read(DiagnosticKind.Storage);var memory=await Read(DiagnosticKind.Memory);var findings=Troubleshooting.Assess(battery,storage,memory);troubleshootingReport=System.Text.Json.JsonSerializer.Serialize(new{Device=device.Serial,CollectedAt=DateTimeOffset.UtcNow,Findings=findings,Errors=errors},new System.Text.Json.JsonSerializerOptions{WriteIndented=true});Output.Text=string.Join("\n\n",findings.Select(x=>$"{x.Severity} | {x.Category}\n{x.Evidence}\n{x.Recommendation}"))+"\n"+string.Join("\n",errors);}catch(Exception ex){Output.Text=ex.Message;}finally{TroubleshootButton.IsEnabled=true;}}
 private async void ExportTroubleshooting(object sender,RoutedEventArgs e){var report=troubleshootingReport;if(report==null){Output.Text="Run an assessment first.";return;}var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-Troubleshooting.json"};if(dialog.ShowDialog()!=true)return;try{await System.IO.File.WriteAllTextAsync(dialog.FileName,report);Output.Text="Assessment exported.";}catch(Exception ex){Output.Text=ex.Message;}}
 private async void Detect(object sender,RoutedEventArgs e){Scan.IsEnabled=false;Output.Text="Detecting devices...";try{var results=await Task.WhenAll(Discovery.ScanAsync("ADB"),Discovery.ScanAsync("Fastboot"));workbenchDevices=results.SelectMany(r=>r.Devices).ToList();RefreshWorkbench();DevicePicker.ItemsSource=results.SelectMany(r=>r.Devices).Where(d=>d.Transport=="ADB"&&d.State=="device").ToList();DevicePicker.SelectedIndex=0;Output.Text=string.Join("\n\n",results.Select(r=>r.Transport+": "+(r.Error??(r.Devices.Count==0?"No devices":string.Join("\n",r.Devices.Select(d=>$"{d.Serial} | {d.State} | {d.Details} | {RecoveryReadiness.Describe(d)}"))))));}catch(Exception ex){Output.Text=ex.Message;}finally{Scan.IsEnabled=true;}}
 private async void ReadDiagnostic(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||DiagnosticPicker.SelectedItem is not DiagnosticKind kind){Output.Text="Select an authorized device after discovery.";return;}ReadButton.IsEnabled=false;try{var security=Navigation.SelectedItem as string=="Security & CVE Lab";var raw=await Diagnostics.ReadAsync(device,security?DiagnosticKind.Identity:kind);if(security||kind==DiagnosticKind.Identity){var identity=IdentityParser.Parse(raw);var oem=OemCompatibility.Identify(identity.Manufacturer);Output.Text=$"Manufacturer: {identity.Manufacturer}\nModel: {identity.Model}\nProduct: {identity.Product}\nAndroid: {identity.AndroidVersion}\nFingerprint: {identity.BuildFingerprint}\nSuggested transport: {oem.SuggestedTransport}\n\n"+string.Join("\n",SecurityAssessment.Assess(identity,DateOnly.FromDateTime(DateTime.UtcNow)).Select(x=>$"{x.Code} | {x.Status} | {x.Detail}"));}else Output.Text=raw;}catch(Exception ex){Output.Text=ex.Message;}finally{ReadButton.IsEnabled=true;}}
 private async void CorrelateBulletin(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Bulletin JSON|*.json",CheckFileExists=true};if(dialog.ShowDialog()!=true)return;BulletinButton.IsEnabled=false;try{if(new System.IO.FileInfo(dialog.FileName).Length>10_000_000)throw new System.IO.InvalidDataException("Catalog exceeds 10 MB.");var entries=BulletinCorrelation.Parse(await System.IO.File.ReadAllTextAsync(dialog.FileName));var identity=IdentityParser.Parse(await Diagnostics.ReadAsync(device,DiagnosticKind.Identity));var findings=BulletinCorrelation.Assess(identity,entries,DateOnly.FromDateTime(DateTime.UtcNow));Output.Text="Imported bulletin records are not independently authenticated. No confirmed vulnerabilities or fixes.\n"+(findings.Count==0?"Empty catalog; no assessment.":string.Join("\n\n",findings.Select(x=>$"{x.Code} | {x.Status} | {x.Detail}")));}catch(Exception ex){Output.Text="Correlation failed: "+ex.Message;}finally{BulletinButton.IsEnabled=true;}}
 private void BrowseFirmware(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Firmware files|*.zip;*.img;*.tar;*.md5;*.bin|All files|*.*",CheckFileExists=true};if(dialog.ShowDialog()==true)FirmwarePath.Text=dialog.FileName;}
 private async void AssessFirmware(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||string.IsNullOrWhiteSpace(FirmwarePath.Text)){Output.Text="Select an authorized device and firmware file.";return;}var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Declared OEM target JSON|*.json",CheckFileExists=true};if(dialog.ShowDialog()!=true)return;ReadinessButton.IsEnabled=false;try{if(new System.IO.FileInfo(dialog.FileName).Length>65536)throw new System.IO.InvalidDataException("Target metadata too large.");var target=System.Text.Json.JsonSerializer.Deserialize<FirmwareTarget>(await System.IO.File.ReadAllTextAsync(dialog.FileName))??throw new System.IO.InvalidDataException("Missing target metadata.");var identity=IdentityParser.Parse(await Diagnostics.ReadAsync(device,DiagnosticKind.Identity));var file=await FirmwareInspector.InspectAsync(FirmwarePath.Text);var result=FirmwareReadiness.Assess(identity,file,target,null);Output.Text=$"Package: {result.PackageType}\nTransport: {OemCompatibility.Identify(identity.Manufacturer).SuggestedTransport}\nFlashing not approved. Metadata is not authenticated.\n"+string.Join("\n",result.Findings.Select(x=>$"{x.Code} | {x.Status} | {x.Detail}"));}catch(Exception ex){Output.Text="Assessment failed: "+ex.Message;}finally{ReadinessButton.IsEnabled=true;}}
 private async void InspectFirmware(object sender,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(FirmwarePath.Text)){Output.Text="Select a firmware file first.";return;}InspectButton.IsEnabled=false;try{Output.Text="Inspecting file...";var expected=ExpectedHash.Text.Trim();var result=await FirmwareInspector.InspectAsync(FirmwarePath.Text,expected.Length==0?null:expected);Output.Text=$"File: {result.Name}\nBytes: {result.Bytes}\nSHA-256: {result.Sha256}\nChecksum: {result.MatchesExpected switch {true=>"Match",false=>"MISMATCH",null=>"Not compared"}}\n\nZIP inventory (up to 1000 entries):\n"+string.Join("\n",result.Entries);}catch(Exception ex){Output.Text="Inspection failed: "+ex.Message;}finally{InspectButton.IsEnabled=true;}}
 private async void RunBackup(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||BackupPicker.SelectedItem is not BackupFolder folder){Output.Text="Detect and select an authorized device first.";return;}var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup destination"};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show($"Copy {folder} from {device.Serial} to a new folder in the selected destination?","Confirm backup",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;BackupButton.IsEnabled=false;try{Output.Text="Copying files...";var result=await SharedStorageBackup.RunAsync(device,folder,dialog.FolderName);Output.Text=$"Backup complete: {result.FileCount} files\n{result.Directory}\nManifest: {result.ManifestPath}";}catch(Exception ex){Output.Text="Backup failed or incomplete: "+ex.Message;}finally{BackupButton.IsEnabled=true;}}
 private async void RestoreBackup(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup root"};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show($"Restore verified backup to a new Download staging folder on {device.Serial}? Original folders will not be overwritten.","Confirm restoration",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;RestoreButton.IsEnabled=false;try{Output.Text="Verifying and transferring backup...";var result=await SharedStorageRestore.RunAsync(device,dialog.FolderName);Output.Text=$"ADB transfer completed: {result.FileCount} manifest files. Staging: {result.Destination}. Device-side checksum verification not performed.";}catch(Exception ex){Output.Text="Restoration failed: "+ex.Message;}finally{RestoreButton.IsEnabled=true;}}
 private async void VerifyBackup(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup root containing manifest.json"};if(dialog.ShowDialog()!=true)return;VerifyButton.IsEnabled=false;try{Output.Text="Verifying backup...";var result=await BackupVerification.VerifyAsync(dialog.FolderName);Output.Text=result.Valid?"Backup matches manifest.":"Verification failed:\n"+string.Join("\n",result.Issues);}catch(Exception ex){Output.Text="Verification failed: "+ex.Message;}finally{VerifyButton.IsEnabled=true;}}
 private async void RequestReboot(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||RebootPicker.SelectedItem is not RebootTarget target){Output.Text="Select an authorized online device.";return;}if(MessageBox.Show($"Reboot {device.Serial} into {target}? Save your work first.","Confirm reboot",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;RebootButton.IsEnabled=false;try{await DeviceReboot.RequestAsync(device,target);Output.Text="Reboot requested. Rescan to verify the resulting mode.";}catch(Exception ex){Output.Text=ex.Message;}finally{RebootButton.IsEnabled=true;}}
 private readonly ServiceHistory serviceHistory=new(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DroidLab","Technician"));
 private async void SaveService(object sender,RoutedEventArgs e){try{var r=await serviceHistory.AddAsync(ServiceSerial.Text,ServiceOperation.Text,ServiceNotes.Text);Output.Text="Saved service record "+r.Id;}catch(Exception ex){Output.Text=ex.Message;}}
 private async void SearchService(object sender,RoutedEventArgs e){try{var records=await serviceHistory.SearchAsync(ServiceQuery.Text);Output.Text=ServiceHistory.Export(records);}catch(Exception ex){Output.Text=ex.Message;}}
 private async void ExportService(object sender,RoutedEventArgs e){try{var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-ServiceHistory.json"};if(dialog.ShowDialog()!=true)return;await System.IO.File.WriteAllTextAsync(dialog.FileName,ServiceHistory.Export(await serviceHistory.SearchAsync(ServiceQuery.Text)));Output.Text="Exported service history.";}catch(Exception ex){Output.Text=ex.Message;}}
 private readonly AdvisoryCache advisoryCache=new(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DroidLab","Advisories"));
 private AdvisorySnapshot? currentAdvisory;
 private void ShowAdvisory(AdvisorySnapshot snapshot,bool cached){currentAdvisory=snapshot;Output.Text=$"{(cached?"CACHED — may be stale":"LIVE")} | {snapshot.Keyword} | Retrieved {snapshot.RetrievedAt:u}\nPublic advisory matches, not confirmed device vulnerabilities. Maximum 50 results.\n\n"+(snapshot.Advisories.Count==0?"No matches returned.":string.Join("\n\n",snapshot.Advisories.Select(x=>$"{x.Id} | CVSS: {x.Score?.ToString()??"Unknown"} | CISA KEV: {(x.KnownExploited?"Listed":"Not listed")}\n{x.Description}")));}
 private async void LoadCachedCve(object sender,RoutedEventArgs e){currentAdvisory=null;try{var snapshot=await advisoryCache.ReadAsync(CveKeyword.Text);if(snapshot==null)Output.Text="No cached results for this keyword.";else ShowAdvisory(snapshot,true);}catch(Exception ex){Output.Text="Cache read failed: "+ex.Message;}}
 private async void ExportCve(object sender,RoutedEventArgs e){var snapshot=currentAdvisory;if(snapshot==null){Output.Text="Search or load cached results first.";return;}var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-Advisories.json"};if(dialog.ShowDialog()!=true)return;try{await System.IO.File.WriteAllTextAsync(dialog.FileName,AdvisoryCache.Report(snapshot));Output.Text="Report exported: "+dialog.FileName;}catch(Exception ex){Output.Text="Export failed: "+ex.Message;}}
 private async void SearchCve(object sender,RoutedEventArgs e){CveButton.IsEnabled=false;currentAdvisory=null;try{Output.Text="Querying public advisory catalogs...";var keyword=CveKeyword.Text.Trim();var items=await VulnerabilityCatalog.SearchAsync(keyword);var snapshot=new AdvisorySnapshot(keyword,DateTimeOffset.UtcNow,items);ShowAdvisory(snapshot,false);try{await advisoryCache.SaveAsync(snapshot);}catch(Exception ex){Output.Text+="\nCache write failed: "+ex.Message;}}catch(Exception ex){Output.Text="Advisory search failed: "+ex.Message;}finally{CveButton.IsEnabled=true;}}
}